// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UserTransitionConfirmer) predicate.UserTransitionConfirmer {
	return predicate.UserTransitionConfirmer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UserTransitionConfirmer) predicate.UserTransitionConfirmer {
	return predicate.UserTransitionConfirmer(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UserTransitionConfirmer) predicate.UserTransitionConfirmer {
	return predicate.UserTransitionConfirmer(sql.NotPredicates(p))
}
